/*
+  Yuktris production-compatible baseline.
+  Effective boundary: production immediately before Phase 2A.
+  Generated from frozen manifest sourced from production_schema.sql.
+  Schema only: no production data, sequence values, auth users, storage objects,
+  vault secrets, credentials, or migration-history rows.
+*/
BEGIN;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '0';
SET LOCAL idle_in_transaction_session_timeout = '0';
SET LOCAL search_path = pg_catalog, public;

-- ============================================================================
-- 1-2. Fail-loud fresh-project and managed-dependency assertions
-- ============================================================================

DO $preflight$
DECLARE
  v_public_tables integer;
  v_public_views integer;
  v_public_sequences integer;
  v_public_functions integer;
BEGIN
  SELECT count(*) INTO v_public_tables FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p');
  SELECT count(*) INTO v_public_views FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m');
  SELECT count(*) INTO v_public_sequences FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='S';
  SELECT count(*) INTO v_public_functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public';
  IF v_public_tables <> 0 OR v_public_views <> 0 OR v_public_sequences <> 0 OR v_public_functions <> 0 THEN
    RAISE EXCEPTION 'Yuktris baseline requires an empty public application schema; found tables %, views %, sequences %, functions %', v_public_tables, v_public_views, v_public_sequences, v_public_functions;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname='auth')
     OR NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname='storage')
     OR NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname='realtime')
     OR NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname='extensions')
     OR NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname='vault') THEN
    RAISE EXCEPTION 'Required Supabase-managed schemas are missing';
  END IF;
  IF to_regclass('auth.users') IS NULL OR to_regclass('storage.buckets') IS NULL OR to_regclass('storage.objects') IS NULL THEN
    RAISE EXCEPTION 'Required Supabase-managed tables are missing';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='anon')
     OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='authenticated')
     OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='service_role')
     OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='postgres') THEN
    RAISE EXCEPTION 'Required Supabase platform roles are missing';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pgcrypto' AND n.nspname='extensions')
     OR NOT EXISTS (SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='uuid-ossp' AND n.nspname='extensions')
     OR NOT EXISTS (SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='pg_stat_statements' AND n.nspname='extensions')
     OR NOT EXISTS (SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace WHERE e.extname='supabase_vault' AND n.nspname='vault') THEN
    RAISE EXCEPTION 'Required extensions are missing or installed in unexpected schemas';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='auth.users'::regclass AND tgname='on_auth_user_created' AND NOT tgisinternal) THEN
    RAISE EXCEPTION 'Collision: auth.users trigger on_auth_user_created already exists';
  END IF;
END
$preflight$;


-- ============================================================================
-- 3. Application sequences
-- ============================================================================

CREATE SEQUENCE "public"."linkedin_accounts_forensic_log_id_seq"
START WITH 1
INCREMENT BY 1
NO MINVALUE
NO MAXVALUE
CACHE 1;


