CREATE OR REPLACE FUNCTION public."cancel_queue_items_for_account"("p_account_id" "uuid") RETURNS "void"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
UPDATE browser_execution_queue
SET status = 'cancelled', completed_at = now()
WHERE account_id = p_account_id
AND status IN ('pending', 'running', 'waiting', 'retry');
END;
$$;

CREATE OR REPLACE FUNCTION public."claim_queue_task"("p_worker_id" "text") RETURNS TABLE("id" "uuid", "workspace_id" "uuid", "account_id" "uuid", "worker_id" "text", "session_id" "uuid", "agent_id" "uuid", "action_type" "text", "action_params" "jsonb", "priority" integer, "priority_label" "text", "status" "text", "retry_count" integer, "max_retries" integer, "next_retry_at" timestamp with time zone, "error" "text", "result" "jsonb", "scheduled_at" timestamp with time zone, "started_at" timestamp with time zone, "completed_at" timestamp with time zone, "duration_ms" integer, "metadata" "jsonb", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
v_task_id UUID;
BEGIN
SELECT browser_execution_queue.id INTO v_task_id
FROM browser_execution_queue
WHERE browser_execution_queue.status IN ('pending', 'retry')
OR (browser_execution_queue.status = 'running'
AND browser_execution_queue.started_at < now() - interval '5 minutes')
ORDER BY
CASE WHEN browser_execution_queue.status IN ('pending', 'retry') THEN 0 ELSE 1 END,
browser_execution_queue.priority ASC,
browser_execution_queue.created_at ASC
LIMIT 1
FOR UPDATE SKIP LOCKED;

IF v_task_id IS NULL THEN
RETURN;
END IF;

UPDATE browser_execution_queue
SET
status = 'running',
worker_id = p_worker_id,
started_at = now(),
updated_at = now()
WHERE browser_execution_queue.id = v_task_id;

RETURN QUERY
SELECT browser_execution_queue.id, browser_execution_queue.workspace_id,
browser_execution_queue.account_id, browser_execution_queue.worker_id,
browser_execution_queue.session_id, browser_execution_queue.agent_id,
browser_execution_queue.action_type, browser_execution_queue.action_params,
browser_execution_queue.priority, browser_execution_queue.priority_label,
browser_execution_queue.status, browser_execution_queue.retry_count,
browser_execution_queue.max_retries, browser_execution_queue.next_retry_at,
browser_execution_queue.error, browser_execution_queue.result,
browser_execution_queue.scheduled_at, browser_execution_queue.started_at,
browser_execution_queue.completed_at, browser_execution_queue.duration_ms,
browser_execution_queue.metadata, browser_execution_queue.created_at,
browser_execution_queue.updated_at
FROM browser_execution_queue
WHERE browser_execution_queue.id = v_task_id;
END;
$$;

CREATE OR REPLACE FUNCTION public."cleanup_old_heartbeats"("p_cutoff" timestamp with time zone) RETURNS "void"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
DELETE FROM linkedin_session_heartbeats
WHERE created_at < p_cutoff;
END;
$$;

CREATE OR REPLACE FUNCTION public."cleanup_old_sessions"() RETURNS integer
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
v_count integer;
BEGIN
DELETE FROM linkedin_sessions
WHERE status = 'expired'
AND updated_at < now() - interval '30 days';

GET DIAGNOSTICS v_count = ROW_COUNT;

DELETE FROM linkedin_sessions
WHERE status = 'revoked'
AND updated_at < now() - interval '7 days';

DELETE FROM linkedin_sessions
WHERE NOT EXISTS (
SELECT 1 FROM linkedin_accounts a WHERE a.id = linkedin_sessions.account_id
);

DELETE FROM linkedin_sessions
WHERE health_status = 'corrupted'
AND updated_at < now() - interval '7 days';

RETURN v_count;
END;
$$;

CREATE OR REPLACE FUNCTION public."complete_queue_task"("p_task_id" "uuid", "p_result" "jsonb", "p_duration_ms" integer) RETURNS "void"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
UPDATE browser_execution_queue
SET status = 'completed', result = p_result, completed_at = now(), duration_ms = p_duration_ms, updated_at = now()
WHERE id = p_task_id;

INSERT INTO browser_execution_history (workspace_id, queue_id, action_type, action_params, status, result, duration_ms, started_at, completed_at)
SELECT workspace_id, id, action_type, action_params, 'completed', p_result, p_duration_ms, started_at, now()
FROM browser_execution_queue WHERE id = p_task_id;
END;
$$;

CREATE OR REPLACE FUNCTION public."delete_session_backups_for_account"("p_account_id" "uuid", "p_workspace_id" "uuid") RETURNS "void"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
DELETE FROM linkedin_session_backups
WHERE account_id = p_account_id
AND workspace_id = p_workspace_id;
END;
$$;

CREATE OR REPLACE FUNCTION public."ensure_single_primary_google_account"() RETURNS "trigger"
LANGUAGE "plpgsql"
SET search_path = pg_catalog, public
AS $$
BEGIN
IF NEW.is_primary THEN
UPDATE google_accounts SET is_primary = false
WHERE workspace_id = NEW.workspace_id AND id != NEW.id;
END IF;
RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public."expire_session"("p_session_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
UPDATE linkedin_sessions
SET
status = 'expired',
health_status = 'expired',
connection_state = 'expired',
failure_reason = p_reason,
updated_at = now()
WHERE id = p_session_id;
END;
$$;

CREATE OR REPLACE FUNCTION public."fail_queue_task"("p_task_id" "uuid", "p_error" "text", "p_duration_ms" integer, "p_retryable" boolean DEFAULT true) RETURNS "void"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
v_task RECORD;
v_next_retry TIMESTAMPTZ;
BEGIN
SELECT * INTO v_task FROM browser_execution_queue WHERE id = p_task_id;
IF v_task.id IS NULL THEN RETURN; END IF;

IF p_retryable AND v_task.retry_count < v_task.max_retries THEN
v_next_retry := now() + least(60 * power(2, v_task.retry_count), 3600) * interval '1 second';
UPDATE browser_execution_queue
SET status = 'retry', error = p_error, retry_count = v_task.retry_count + 1,
next_retry_at = v_next_retry, completed_at = now(), duration_ms = p_duration_ms, updated_at = now()
WHERE id = p_task_id;
ELSE
UPDATE browser_execution_queue
SET status = 'failed', error = p_error, completed_at = now(), duration_ms = p_duration_ms, updated_at = now()
WHERE id = p_task_id;

INSERT INTO browser_execution_history (workspace_id, queue_id, action_type, action_params, status, error, duration_ms, started_at, completed_at)
VALUES (v_task.workspace_id, v_task.id, v_task.action_type, v_task.action_params, 'failed', p_error, p_duration_ms, v_task.started_at, now());

INSERT INTO browser_dead_letter_queue (id, workspace_id, execution_id, original_queue_id, account_id, action_type, action_params, failure_reason, retry_count, last_error)
VALUES (gen_random_uuid(), v_task.workspace_id, gen_random_uuid(), v_task.id, v_task.account_id, v_task.action_type, v_task.action_params, p_error, v_task.retry_count, p_error);
END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public."generate_workspace_slug"("ws_name" "text") RETURNS "text"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
base_slug text;
candidate_slug text;
counter integer := 0;
BEGIN
PERFORM pg_advisory_xact_lock(987654321);

base_slug := lower(regexp_replace(ws_name, '[^a-zA-Z0-9]+', '-', 'g'));
base_slug := trim(both '-' from base_slug);
base_slug := CASE WHEN base_slug = '' THEN 'workspace' ELSE base_slug END;
LOOP
candidate_slug := CASE WHEN counter = 0 THEN base_slug ELSE base_slug || '-' || counter END;
EXIT WHEN NOT EXISTS (SELECT 1 FROM public.workspaces w WHERE w.slug = candidate_slug);
counter := counter + 1;
END LOOP;
RETURN candidate_slug;
END;
$$;

