CREATE OR REPLACE FUNCTION public."get_google_secret"("secret_name" "text") RETURNS "text"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public, 'vault'
AS $$
DECLARE
secret_value text;
BEGIN
IF secret_name IS NULL OR LEFT(secret_name, 7) != 'GOOGLE_' THEN
RETURN NULL;
END IF;

SELECT decrypted_secret INTO secret_value
FROM vault.decrypted_secrets
WHERE name = secret_name
LIMIT 1;

RETURN secret_value;
END;
$$;

CREATE OR REPLACE FUNCTION public."graph_most_connected"("p_workspace_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 10) RETURNS TABLE("node_id" "uuid", "display_name" "text", "degree" bigint)
LANGUAGE "plpgsql"
SET search_path = pg_catalog, public
AS $$
BEGIN
RETURN QUERY
SELECT
gn.id AS node_id,
gn.display_name AS display_name,
degree_calc.deg::bigint AS degree
FROM (
SELECT n_id, SUM(edge_count)::bigint AS deg
FROM (
SELECT source_node_id AS n_id, COUNT(*)::bigint AS edge_count
FROM graph_edges
WHERE is_deleted = false
AND (p_workspace_id IS NULL OR workspace_id = p_workspace_id)
GROUP BY source_node_id

UNION ALL

SELECT target_node_id AS n_id, COUNT(*)::bigint AS edge_count
FROM graph_edges
WHERE is_deleted = false
AND (p_workspace_id IS NULL OR workspace_id = p_workspace_id)
GROUP BY target_node_id
) AS combined
GROUP BY n_id
) AS degree_calc
JOIN graph_nodes gn ON gn.id = degree_calc.n_id
WHERE gn.is_deleted = false
ORDER BY degree_calc.deg DESC
LIMIT p_limit;
END;
$$;

CREATE OR REPLACE FUNCTION public."graph_neighborhood"("p_start_node_id" "uuid", "p_max_depth" integer DEFAULT 2, "p_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("node_id" "uuid", "node_type" "text", "display_name" "text", "depth" integer, "edge_id" "uuid", "edge_type" "text", "source_node_id" "uuid", "confidence_score" numeric)
LANGUAGE "plpgsql"
SET search_path = pg_catalog, public
AS $$
BEGIN
RETURN QUERY
WITH RECURSIVE traversal AS (
SELECT
ge.target_node_id AS node_id,
gn.node_type,
gn.display_name,
1 AS depth,
ge.id AS edge_id,
ge.relationship_type AS edge_type,
ge.source_node_id,
ge.confidence_score
FROM graph_edges ge
JOIN graph_nodes gn ON gn.id = ge.target_node_id
WHERE ge.source_node_id = p_start_node_id
AND ge.is_deleted = false
AND gn.is_deleted = false
AND (p_workspace_id IS NULL OR ge.workspace_id = p_workspace_id)

UNION ALL

SELECT
ge.target_node_id AS node_id,
gn.node_type,
gn.display_name,
t.depth + 1,
ge.id AS edge_id,
ge.relationship_type AS edge_type,
ge.source_node_id,
ge.confidence_score
FROM graph_edges ge
JOIN graph_nodes gn ON gn.id = ge.target_node_id
JOIN traversal t ON t.node_id = ge.source_node_id
WHERE t.depth < p_max_depth
AND ge.is_deleted = false
AND gn.is_deleted = false
AND ge.target_node_id != p_start_node_id
AND (p_workspace_id IS NULL OR ge.workspace_id = p_workspace_id)
)
SELECT DISTINCT ON (node_id)
node_id, node_type, display_name, depth, edge_id, edge_type, source_node_id, confidence_score
FROM traversal
ORDER BY node_id, depth;
END;
$$;

CREATE OR REPLACE FUNCTION public."graph_shortest_path"("p_source_node_id" "uuid", "p_target_node_id" "uuid", "p_max_depth" integer DEFAULT 5, "p_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("node_id" "uuid", "node_type" "text", "display_name" "text", "step" integer, "edge_type" "text")
LANGUAGE "plpgsql"
SET search_path = pg_catalog, public
AS $$
BEGIN
RETURN QUERY
WITH RECURSIVE bfs AS (
SELECT
p_source_node_id AS node_id,
gn.node_type,
gn.display_name,
0 AS step,
''::text AS edge_type,
ARRAY[p_source_node_id] AS path
FROM graph_nodes gn
WHERE gn.id = p_source_node_id

UNION ALL

SELECT
ge.target_node_id AS node_id,
gn.node_type,
gn.display_name,
b.step + 1,
ge.relationship_type AS edge_type,
b.path || ge.target_node_id
FROM bfs b
JOIN graph_edges ge ON ge.source_node_id = b.node_id
JOIN graph_nodes gn ON gn.id = ge.target_node_id
WHERE b.step < p_max_depth
AND ge.is_deleted = false
AND gn.is_deleted = false
AND NOT (ge.target_node_id = ANY(b.path))
AND (p_workspace_id IS NULL OR ge.workspace_id = p_workspace_id)
)
SELECT node_id, node_type, display_name, step, edge_type
FROM bfs
WHERE node_id = p_target_node_id
ORDER BY step
LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION public."handle_new_user"() RETURNS "trigger"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
ws_id uuid;
full_name text;
first_name text;
last_name text;
BEGIN
full_name := COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.email);

first_name := split_part(full_name, ' ', 1);
last_name := CASE
WHEN position(' ' in full_name) > 0
THEN substring(full_name from position(' ' in full_name) + 1)
ELSE NULL
END;

INSERT INTO public.profiles (id, email, first_name, last_name)
VALUES (NEW.id, NEW.email, first_name, last_name)
ON CONFLICT (id) DO NOTHING;

SELECT w.id INTO ws_id
FROM public.workspaces w
JOIN public.workspace_members wm ON wm.workspace_id = w.id
WHERE wm.user_id = NEW.id AND wm.status = 'active'
LIMIT 1;

IF ws_id IS NULL THEN
INSERT INTO public.workspaces (name, owner_id, onboarding_completed)
VALUES ('My Workspace', NEW.id, false)
RETURNING id INTO ws_id;

INSERT INTO public.workspace_members (workspace_id, user_id, role, status)
VALUES (ws_id, NEW.id, 'owner', 'active')
ON CONFLICT DO NOTHING;

UPDATE public.profiles
SET workspace_id = ws_id, role = 'owner'
WHERE id = NEW.id;
END IF;

RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public."heartbeat_browser_worker"("p_worker_id" "text", "p_status" "text" DEFAULT 'idle'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
