CREATE OR REPLACE FUNCTION public."is_workspace_member"("check_workspace_id" "uuid") RETURNS boolean
LANGUAGE "sql"
SET search_path = pg_catalog, public, pg_temp
AS $$
SELECT EXISTS (
SELECT 1 FROM workspace_members
WHERE workspace_members.workspace_id = check_workspace_id
AND workspace_members.user_id = auth.uid()
);
$$;

CREATE OR REPLACE FUNCTION public."load_latest_linkedin_session"("p_account_id" "uuid") RETURNS TABLE("id" "uuid", "workspace_id" "uuid", "account_id" "uuid", "session_name" "text", "cookies_encrypted" "text", "storage_state_encrypted" "text", "local_storage_encrypted" "text", "session_storage_encrypted" "text", "encrypted" boolean, "encryption_key_id" "text", "user_agent" "text", "viewport" "jsonb", "timezone" "text", "locale" "text", "language" "text", "browser_version" "text", "playwright_version" "text", "browserbase_session_id" "text", "browser_fingerprint" "jsonb", "status" "text", "connection_state" "text", "health_status" "text", "authenticated" boolean, "authenticated_at" timestamp with time zone, "last_validated_at" timestamp with time zone, "last_used_at" timestamp with time zone, "last_activity_at" timestamp with time zone, "expires_at" timestamp with time zone, "failure_reason" "text", "retry_count" integer, "metadata" "jsonb")
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
RETURN QUERY
SELECT
s.id, s.workspace_id, s.account_id, s.session_name,
s.cookies_encrypted, s.storage_state_encrypted,
s.local_storage_encrypted, s.session_storage_encrypted,
s.encrypted, s.encryption_key_id,
s.user_agent, s.viewport,
s.timezone, s.locale, s.language,
s.browser_version, s.playwright_version,
s.browserbase_session_id, s.browser_fingerprint,
s.status, s.connection_state, s.health_status,
s.authenticated, s.authenticated_at,
s.last_validated_at, s.last_used_at, s.last_activity_at,
s.expires_at, s.failure_reason, s.retry_count,
s.metadata
FROM linkedin_sessions s
WHERE s.account_id = p_account_id
AND s.status = 'active'
ORDER BY s.created_at DESC
LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION public."log_linkedin_accounts_delete"() RETURNS "trigger"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
v_pid BIGINT;
v_user TEXT;
v_app TEXT;
v_addr TEXT;
v_query TEXT;
BEGIN
v_pid := pg_backend_pid();
SELECT usename INTO v_user FROM pg_stat_activity WHERE pid = v_pid;
SELECT application_name INTO v_app FROM pg_stat_activity WHERE pid = v_pid;
SELECT client_addr::text INTO v_addr FROM pg_stat_activity WHERE pid = v_pid;
SELECT query INTO v_query FROM pg_stat_activity WHERE pid = v_pid;

INSERT INTO linkedin_accounts_forensic_log (
operation, account_id, workspace_id, old_data,
caller_query, caller_pid, caller_user, caller_application, caller_addr
) VALUES (
'DELETE', OLD.id, OLD.workspace_id, to_jsonb(OLD),
left(v_query, 5000), v_pid, v_user, v_app, v_addr
);

RETURN OLD;
END;
$$;

CREATE OR REPLACE FUNCTION public."log_linkedin_accounts_insert"() RETURNS "trigger"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
v_pid BIGINT;
v_user TEXT;
v_app TEXT;
v_addr TEXT;
v_query TEXT;
BEGIN
v_pid := pg_backend_pid();
SELECT usename INTO v_user FROM pg_stat_activity WHERE pid = v_pid;
SELECT application_name INTO v_app FROM pg_stat_activity WHERE pid = v_pid;
SELECT client_addr::text INTO v_addr FROM pg_stat_activity WHERE pid = v_pid;
SELECT query INTO v_query FROM pg_stat_activity WHERE pid = v_pid;

INSERT INTO linkedin_accounts_forensic_log (
operation, account_id, workspace_id, new_data,
caller_query, caller_pid, caller_user, caller_application, caller_addr
) VALUES (
'INSERT', NEW.id, NEW.workspace_id, to_jsonb(NEW),
left(v_query, 5000), v_pid, v_user, v_app, v_addr
);

RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public."log_linkedin_accounts_update"() RETURNS "trigger"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
v_pid BIGINT;
v_user TEXT;
v_app TEXT;
v_addr TEXT;
v_query TEXT;
v_changed TEXT[];
BEGIN
v_pid := pg_backend_pid();
SELECT usename INTO v_user FROM pg_stat_activity WHERE pid = v_pid;
SELECT application_name INTO v_app FROM pg_stat_activity WHERE pid = v_pid;
SELECT client_addr::text INTO v_addr FROM pg_stat_activity WHERE pid = v_pid;
SELECT query INTO v_query FROM pg_stat_activity WHERE pid = v_pid;

SELECT array_agg(key) INTO v_changed
FROM jsonb_each(to_jsonb(NEW))
WHERE to_jsonb(OLD)->>key IS DISTINCT FROM value#>>'{}';

INSERT INTO linkedin_accounts_forensic_log (
operation, account_id, workspace_id, old_data, new_data, changed_columns,
caller_query, caller_pid, caller_user, caller_application, caller_addr
) VALUES (
'UPDATE', NEW.id, NEW.workspace_id, to_jsonb(OLD), to_jsonb(NEW), v_changed,
left(v_query, 5000), v_pid, v_user, v_app, v_addr
);

RETURN NEW;
END;
$$;

