CREATE OR REPLACE FUNCTION public."recover_orphaned_queue_tasks"("p_timeout_minutes" integer DEFAULT 10) RETURNS integer
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
v_count integer;
v_cutoff timestamptz;
BEGIN
v_cutoff := now() - (p_timeout_minutes || ' minutes')::interval;

UPDATE browser_execution_queue
SET status = 'pending',
worker_id = NULL,
started_at = NULL,
error = 'Recovered from orphaned worker',
updated_at = now()
WHERE status IN ('running', 'processing')
AND started_at IS NOT NULL
AND started_at < v_cutoff
AND worker_id IS NOT NULL;

GET DIAGNOSTICS v_count = ROW_COUNT;

RETURN v_count;
END;
$$;

CREATE OR REPLACE FUNCTION public."refresh_session_data"("p_session_id" "uuid", "p_cookies_encrypted" "text" DEFAULT NULL::"text", "p_storage_state_encrypted" "text" DEFAULT NULL::"text", "p_local_storage_encrypted" "text" DEFAULT NULL::"text", "p_session_storage_encrypted" "text" DEFAULT NULL::"text", "p_last_verified_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
UPDATE linkedin_sessions
SET
cookies_encrypted = COALESCE(p_cookies_encrypted, cookies_encrypted),
storage_state_encrypted = COALESCE(p_storage_state_encrypted, storage_state_encrypted),
local_storage_encrypted = COALESCE(p_local_storage_encrypted, local_storage_encrypted),
session_storage_encrypted = COALESCE(p_session_storage_encrypted, session_storage_encrypted),
last_validated_at = COALESCE(p_last_verified_at, last_validated_at),
expires_at = COALESCE(p_expires_at, expires_at),
last_used_at = now(),
updated_at = now()
WHERE id = p_session_id;
END;
$$;

CREATE OR REPLACE FUNCTION public."register_browser_worker"("p_worker_id" "text", "p_worker_name" "text", "p_workspace_id" "uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
v_id UUID;
BEGIN
SELECT id INTO v_id FROM browser_workers WHERE worker_id = p_worker_id LIMIT 1;

IF v_id IS NOT NULL THEN
UPDATE browser_workers
SET status = 'idle', browser_version = p_metadata->>'chromium_version',
metadata = p_metadata, updated_at = now()
WHERE id = v_id;
RETURN v_id;
END IF;

INSERT INTO browser_workers (
id, workspace_id, worker_id, provider, status, browser_version, metadata
) VALUES (
gen_random_uuid(), p_workspace_id, p_worker_id, 'linkedin', 'idle',
p_metadata->>'chromium_version', p_metadata
)
RETURNING id INTO v_id;

RETURN v_id;
END;
$$;

CREATE OR REPLACE FUNCTION public."revoke_sessions_for_account"("p_account_id" "uuid", "p_workspace_id" "uuid") RETURNS "void"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
UPDATE linkedin_sessions
SET status = 'revoked'
WHERE account_id = p_account_id
AND workspace_id = p_workspace_id;
END;
$$;

CREATE OR REPLACE FUNCTION public."save_linkedin_session"("p_workspace_id" "uuid", "p_account_id" "uuid", "p_session_name" "text", "p_cookies_encrypted" "text", "p_storage_state_encrypted" "text", "p_local_storage_encrypted" "text", "p_session_storage_encrypted" "text", "p_encryption_key_id" "text" DEFAULT 'li-session-aes256-gcm-v3'::"text", "p_user_agent" "text" DEFAULT NULL::"text", "p_viewport" "jsonb" DEFAULT NULL::"jsonb", "p_browser_version" "text" DEFAULT NULL::"text", "p_playwright_version" "text" DEFAULT NULL::"text", "p_timezone" "text" DEFAULT NULL::"text", "p_language" "text" DEFAULT NULL::"text", "p_browserbase_session_id" "text" DEFAULT NULL::"text", "p_browser_fingerprint" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
DECLARE
v_session_id uuid;
BEGIN
UPDATE linkedin_sessions
SET status = 'expired', updated_at = now()
WHERE account_id = p_account_id
AND status = 'active';

INSERT INTO linkedin_sessions (
workspace_id, account_id, session_name,
cookies_encrypted, storage_state_encrypted,
local_storage_encrypted, session_storage_encrypted,
encrypted, encryption_key_id,
user_agent, viewport,
browser_version, playwright_version,
timezone, locale, language,
browserbase_session_id, browser_fingerprint,
status, connection_state, health_status,
authenticated, authenticated_at,
last_validated_at, last_used_at, expires_at,
metadata
) VALUES (
p_workspace_id, p_account_id, p_session_name,
p_cookies_encrypted, p_storage_state_encrypted,
p_local_storage_encrypted, p_session_storage_encrypted,
true, p_encryption_key_id,
p_user_agent, p_viewport,
p_browser_version, p_playwright_version,
p_timezone, p_language, p_language,
p_browserbase_session_id, p_browser_fingerprint,
'active', 'authenticated', 'healthy',
true, now(),
now(), now(), now() + interval '7 days',
'{}'::jsonb
)
RETURNING id INTO v_session_id;

RETURN v_session_id;
END;
$$;

