CREATE OR REPLACE FUNCTION public."update_session_health"("p_session_id" "uuid", "p_health_status" "text", "p_failure_reason" "text" DEFAULT NULL::"text", "p_connection_state" "text" DEFAULT NULL::"text") RETURNS "void"
LANGUAGE "plpgsql" SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
UPDATE linkedin_sessions
SET
health_status = p_health_status,
failure_reason = p_failure_reason,
connection_state = COALESCE(p_connection_state, connection_state),
updated_at = now()
WHERE id = p_session_id;
END;
$$;

