-- ============================================================================
-- 10. Views
-- ============================================================================

CREATE OR REPLACE VIEW "public"."linkedin_session_public_view" AS
SELECT "id",
"workspace_id",
"account_id",
"session_name",
"encrypted",
"encryption_key_id",
"user_agent",
"viewport",
"timezone",
"locale",
"language",
"browser_version",
"playwright_version",
"browserbase_session_id",
"browser_fingerprint",
"status",
"connection_state",
"health_status",
"authenticated",
"authenticated_at",
"last_validated_at",
"last_used_at",
"last_activity_at",
"expires_at",
"failure_reason",
"retry_count",
"metadata",
"created_at",
"updated_at"
FROM "public"."linkedin_sessions"
WHERE ("status" = ANY (ARRAY['active'::"text", 'expired'::"text", 'revoked'::"text"]));


