-- ============================================================================
-- 16. Application-owned auth trigger wiring
-- ============================================================================

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_new_user();


-- ============================================================================
-- 17. In-transaction validation assertions
-- ============================================================================

DO $validate$
DECLARE
  v_tables integer; v_columns integer; v_pks integer; v_fks integer; v_indexes integer;
  v_functions integer; v_triggers integer; v_policies integer; v_views integer; v_sequences integer; v_rls integer;
BEGIN
  SELECT count(*) INTO v_tables FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p');
  SELECT count(*) INTO v_columns FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND a.attnum>0 AND NOT a.attisdropped;
  SELECT count(*) FILTER (WHERE con.contype='p'), count(*) FILTER (WHERE con.contype='f') INTO v_pks,v_fks FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public';
  SELECT count(*) INTO v_indexes FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT i.indisprimary AND NOT EXISTS (SELECT 1 FROM pg_constraint con WHERE con.conindid=i.indexrelid);
  SELECT count(*) INTO v_functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public';
  SELECT count(*) INTO v_triggers FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal;
  SELECT count(*) INTO v_policies FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public';
  SELECT count(*) INTO v_views FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='v';
  SELECT count(*) INTO v_sequences FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='S';
  SELECT count(*) INTO v_rls FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND c.relrowsecurity;
  IF (v_tables,v_columns,v_pks,v_fks,v_indexes,v_functions,v_triggers,v_policies,v_views,v_sequences,v_rls) IS DISTINCT FROM (673,8533,673,1181,1621,96,450,2636,1,1,673) THEN
    RAISE EXCEPTION 'Baseline count mismatch: tables %, columns %, PK %, FK %, indexes %, functions %, triggers %, policies %, views %, sequences %, RLS %', v_tables,v_columns,v_pks,v_fks,v_indexes,v_functions,v_triggers,v_policies,v_views,v_sequences,v_rls;
  END IF;
  IF to_regclass('public.stripe_customers') IS NOT NULL OR to_regclass('public.stripe_invoices') IS NOT NULL OR to_regclass('public.stripe_payment_intents') IS NOT NULL OR to_regclass('public.stripe_subscriptions') IS NOT NULL OR to_regclass('public.stripe_webhook_events') IS NOT NULL THEN
    RAISE EXCEPTION 'Legacy Stripe table detected';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND ((table_name='browser_execution_queue' AND column_name IN ('attempt_id','lease_expires_at','idempotency_key')) OR (table_name='linkedin_accounts' AND column_name='expected_profile_url')))
     OR to_regprocedure('public.renew_queue_lease(uuid,text,uuid,integer)') IS NOT NULL
     OR to_regclass('public.uq_browser_queue_idempotency') IS NOT NULL
     OR to_regclass('public.idx_browser_queue_claimable') IS NOT NULL
     OR EXISTS (SELECT 1 FROM pg_constraint WHERE conname='linkedin_auth_interactions_no_secrets') THEN
    RAISE EXCEPTION 'Phase 2A boundary violation';
  END IF;
END
$validate$;


-- ============================================================================
-- 17b. Constraint validation gate
-- ============================================================================

DO $constraints_validated$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint con JOIN pg_namespace n ON n.oid=con.connamespace WHERE n.nspname='public' AND NOT con.convalidated) THEN
    RAISE EXCEPTION 'Baseline contains one or more unvalidated public constraints';
  END IF;
END
$constraints_validated$;


-- 18. Commit only after every assertion succeeds.
COMMIT;
